package LFFC01;

public class LFFC36 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		 System.out.println("***********************************");
	        System.out.println("* Aluno: LUIZ FELIPE FREIRE DA CRUZ - RA 0023623*");
	        System.out.println("* Classe LFFC36 - Contagem regressiva de 10 até 1 *");
	        System.out.println("***********************************");

	        

	        int i = 10;
	        
	        System.out.println("Contagem regressiva (do-while):");
	        
	        do {
	            System.out.println(i);
	            i--;
	        } while (i >= 1);
	}

}
